// Des: POSIX orphan tracking: lock file, sweep dead process groups
// Flo: track pgid > untrack at exit > sweep leftovers on boot
// I/O: pid + start time > lock file; sweep > killed count
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const regi = @import("registry"); const stre = @import("stream"); const cwdi = @import("cwd"); const stor = @import("store");
const ruspawbase = @import("ru-spaw-base.zig"); const CF = ruspawbase.CF; const CMDZ_ENVI_VARZ = ruspawbase.CMDZ_ENVI_VARZ; const TIME_CODE = ruspawbase.TIME_CODE; const chilSpaw = ruspawbase.chilSpaw; const enviExpa = ruspawbase.enviExpa; const mute_spaw = ruspawbase.mute_spaw; const nowzMsec = ruspawbase.nowzMsec; const runzCapt = ruspawbase.runzCapt;
const Orph = struct { pgid: i32, star: u64 }; var orph_mute: std.Io.Mutex = .init; var orph_list: [CF.orph_maxz]Orph = undefined; var orph_coun: usize = 0;
pub fn orphTrac(allo: std.mem.Allocator, iozz: std.Io, pidz: i32) void { const star = procStar(iozz, pidz) orelse return; orph_mute.lock(iozz) catch return; defer orph_mute.unlock(iozz); if (orph_coun >= CF.orph_maxz) return; orph_list[orph_coun] = .{ .pgid = pidz, .star = star }; orph_coun += 1; orphLockSave(allo, iozz); }
pub fn orphUntr(allo: std.mem.Allocator, iozz: std.Io, pidz: i32) void { orph_mute.lock(iozz) catch return; defer orph_mute.unlock(iozz); var indx: usize = 0; while (indx < orph_coun) : (indx += 1) { if (orph_list[indx].pgid != pidz) continue; orph_list[indx] = orph_list[orph_coun - 1]; orph_coun -= 1; orphLockSave(allo, iozz); return; } }
fn orphLockSave(allo: std.mem.Allocator, iozz: std.Io) void { var outz: std.Io.Writer.Allocating = .init(allo); defer outz.deinit(); var boot_buff: [64]u8 = undefined; const boot = bootKeyz(iozz, &boot_buff); for (orph_list[0..orph_coun]) |item| outz.writer.print("{d} {d} {s}\n", .{ item.pgid, item.star, boot }) catch return; stor.save(allo, iozz, CF.orph_file, outz.writer.buffered()) catch {}; }
pub fn orphSwee(allo: std.mem.Allocator, iozz: std.Io) usize { if (builtin.os.tag == .windows) return 0; const rawz = stor.load(allo, iozz, CF.orph_file); var boot_buff: [64]u8 = undefined; const boot = bootKeyz(iozz, &boot_buff); var kill: usize = 0; var iter = std.mem.splitScalar(u8, rawz, '\n'); while (iter.next()) |line| { var toke = std.mem.tokenizeScalar(u8, line, ' '); const pgrp = std.fmt.parseInt(i32, toke.next() orelse continue, 10) catch continue; const star = std.fmt.parseInt(u64, toke.next() orelse continue, 10) catch continue; const bkey = toke.next() orelse "-"; if (pgrp <= 1 or !std.mem.eql(u8, bkey, boot)) continue; if ((procStar(iozz, pgrp) orelse continue) != star) continue; std.posix.kill(-pgrp, std.posix.SIG.TERM) catch {}; std.posix.kill(-pgrp, std.posix.SIG.KILL) catch {}; kill += 1; } stor.save(allo, iozz, CF.orph_file, "") catch {}; return kill; }
fn procStar(iozz: std.Io, pidz: i32) ?u64 { switch (builtin.os.tag) { .linux => { var pbuf: [32]u8 = undefined; const path = std.fmt.bufPrint(&pbuf, "/proc/{d}/stat", .{pidz}) catch return null; var file = std.Io.Dir.cwd().openFile(iozz, path, .{}) catch return null; defer file.close(iozz); var buff: [1024]u8 = undefined; const size = file.readPositionalAll(iozz, &buff, 0) catch return null; const strz = buff[0..size]; const rpar = std.mem.lastIndexOfScalar(u8, strz, ')') orelse return null; var iter = std.mem.tokenizeScalar(u8, strz[rpar + 1 ..], ' '); var indx: usize = 0; while (iter.next()) |toke| : (indx += 1) { if (indx == 19) return std.fmt.parseInt(u64, toke, 10) catch null; } return null; }, .macos => { var mibz = [4]c_int{ 1, 14, 1, pidz }; var info: [648]u8 align(8) = undefined; var leng: usize = info.len; if (std.c.sysctl(&mibz, 4, &info, &leng, null, 0) != 0 or leng == 0) return null; const secz = std.mem.readInt(i64, info[0..8], .little); const usec = std.mem.readInt(i32, info[8..12], .little); return @as(u64, @intCast(secz)) * 1_000_000 + @as(u64, @intCast(usec)); }, else => return null, } }
fn bootKeyz(iozz: std.Io, buff: []u8) []const u8 { if (builtin.os.tag != .linux) return "-"; var file = std.Io.Dir.cwd().openFile(iozz, "/proc/sys/kernel/random/boot_id", .{}) catch return "-"; defer file.close(iozz); const size = file.readPositionalAll(iozz, buff, 0) catch return "-"; return std.mem.trim(u8, buff[0..size], " \r\n"); }
